function bilinear(t,u,v){const x=u*t.width-.5,y=v*t.height-.5,ix=Math.floor(x),iy=Math.floor(y),fx=x-ix,fy=y-iy;const read=(a,b,k)=>t.data[(Math.max(0,Math.min(t.height-1,b))*t.width+((a%t.width+t.width)%t.width))*4+k];const out=[];for(let k=0;k<3;k++)out.push((read(ix,iy,k)*(1-fx)+read(ix+1,iy,k)*fx)*(1-fy)+(read(ix,iy+1,k)*(1-fx)+read(ix+1,iy+1,k)*fx)*fy);return out;}

